+    const vec_f32 zerosf = hn::Zero(f32);
+    const vec_s32 ones  = hn::Set(s32, 1);
+    const vec_s32 twos  = hn::Set(s32, 2);
+    const vec_f32 two_over_pi = hn::Set(f32, 0x1.45f306p-1f);
