+        for (; len > 0; --len, src += ssrc, dst += sdst) {
+            simd_sincos_f32(src, 1, dst, 1, 1, SIMD_COMPUTE_SIN);
+        }
+    } else {
+        simd_sincos_f32(src, ssrc, dst, sdst, len, SIMD_COMPUTE_SIN);
+    }
+#else
+    UNARY_LOOP {
+        const npy_float in1 = *(npy_float *)ip1;
+        *(npy_float *)op1 = npy_sinf(in1);
+    }
+#endif
+}
